		return result.toList();
	}

	private void addOnXError(String errorName) {
		if (getLatestJavaSpecSupported() < 8) {
			addError("The correct format up to JDK7 is " + errorName + "=@__({@SomeAnnotation, @SomeOtherAnnotation}))");
		} else {
			addError("The correct format for JDK8+ is " + errorName + "_={@SomeAnnotation, @SomeOtherAnnotation})");
		}
	}

